#!/usr/bin/env python3
"""Extend the Leo whole-object drag to the existing Snap to Glyph anchors."""
from pathlib import Path
import sys

root = Path(sys.argv[1]) / "crates/tools/src"
edits = {
    "guides/targets.rs": [
        ("impl Kind {", "/// Uses the same positioned outlines as the drawing tool's Snap to Glyph.\npub(crate) fn grab_glyph_anchor(cx: &ToolContext, id: NodeId, p: Point, reach: f64) -> Option<Point> {\n    if !glyph_move_enabled(cx) { return None; }\n    let node = cx.doc.node(id).filter(|n| n.visible && !n.locked)?;\n    let NodeKind::Text(t) = &node.kind else { return None };\n    let layout = layout_text(FontDb::global(), t);\n    if layout.lines.len() != 1 { return None; }\n    layout.glyphs.iter().flat_map(|g| g.outline.segments())\n        .map(|s| t.xf * s.start())\n        .filter(|q| q.distance(p) <= reach)\n        .min_by(|a, b| a.distance(p).total_cmp(&b.distance(p)))\n}\n\nfn glyph_move_enabled(cx: &ToolContext) -> bool {\n    cx.leo_snapping && cx.smart_guides && cx.snap_to_glyph && cx.glyph_snap.anchors && !cx.snap_to_grid\n}\n\nimpl Kind {", 1),
        ("    /// Targets for moving the selection of `cx`", "    /// Freeze visible glyph outlines once per move; exclude the moved selection unless copying.\n    fn glyph_move_targets(cx: &ToolContext, exclude: &[NodeId]) -> Self {\n        let mut t = Self::default().styled(cx);\n        let visible = super::snap::visible(cx);\n        t.push_glyphs(cx.doc, exclude, visible, GlyphSnap {\n            anchors: true, baseline: false, x_height: false, bounds: false,\n            proximity: false, angular: false,\n        });\n        t.points.retain(|(p, _)| p.is_finite() && visible.is_none_or(|r| r.contains(*p)));\n        for &(p, kind) in &t.points {\n            t.xs.push((p.x, p, kind));\n            t.ys.push((p.y, p, kind));\n        }\n        t.index()\n    }\n\n    /// Targets for moving the selection of `cx`", 1),
    ],
    "guides/snap.rs": [
        ("fn visible(cx: &ToolContext)", "pub(super) fn visible(cx: &ToolContext)", 1),
    ],
    "guides.rs": [
        ("pub use targets::Targets;", "pub use targets::Targets;\npub(crate) use targets::grab_glyph_anchor;", 1),
    ],
    "select.rs": [
        ("        let under = hit_test(cx.doc, p, cx.selection_hit_options()).map(|h| h.top_object(cx.isolation));", "        let hit = hit_test(cx.doc, p, cx.selection_hit_options());\n        if let Some(q) = hit.as_ref().and_then(|h| crate::guides::grab_glyph_anchor(cx, h.leaf, p, reach)) {\n            return Some((q, \"anchor\"));\n        }\n        let under = hit.map(|h| h.top_object(cx.isolation));", 1),
        ("                let anchor = n.path_data().and_then", "                if under.is_none() && let Some(q) = crate::guides::grab_glyph_anchor(cx, id, p, reach) {\n                    return Some((q, \"anchor\"));\n                }\n                let anchor = n.path_data().and_then", 1),
    ],
    "guides/leo_snapping_engine.rs": [
        ("pub(crate) struct ObjectMoveSnap {", "pub(crate) struct ObjectMoveSnap {\n    glyph: Option<GlyphMoveSnap>,", 1),
        ("            edges: selected_edges(cx),", "            edges: selected_edges(cx),\n            glyph: glyph_move_enabled(cx).then(|| GlyphMoveSnap::new(cx)),", 1),
        ("            edges: vec![],", "            edges: vec![],\n            glyph: None,", 2),
        ("        self.lock.get().is_some() || self.x_lock.get().is_some() || self.y_lock.get().is_some()", "        self.lock.get().is_some() || self.x_lock.get().is_some() || self.y_lock.get().is_some()\n            || self.glyph.as_ref().is_some_and(|glyph| glyph.lock.get().is_some())", 1),
        ("        self.y_lock.set(None);\n    }\n\n    fn targets(&self", "        self.y_lock.set(None);\n        if let Some(glyph) = &self.glyph { glyph.lock.set(None); }\n    }\n\n    fn targets(&self", 1),
        ("        let targets = self.targets(copy);", "        if let Some(glyph) = &self.glyph\n            && let Some(result) = glyph.snap(start, d, copy, acquire, release, direction)\n        {\n            self.lock.set(None);\n            self.x_lock.set(None);\n            self.y_lock.set(None);\n            return result;\n        }\n        let targets = self.targets(copy);", 1),
        ("fn move_hit_guides(targets: &Targets", "/// A drag held at a real glyph point. Whole-object translation keeps type editable.\nstruct GlyphMoveSnap {\n    sources: Targets,\n    targets: Targets,\n    lock: Cell<Option<(Point, Option<bool>)>>,\n}\n\nimpl GlyphMoveSnap {\n    fn new(cx: &ToolContext) -> Self {\n        let mut sources = Targets::default();\n        let selected: HashSet<NodeId> = cx.selection.objects.iter().copied().collect();\n        // Visit the moved selection, including text inside a moved group.\n        fn selected_text(nodes: &[Arc<Node>], selected: &HashSet<NodeId>, inherited: bool, points: &mut Vec<(Point, Kind)>) {\n            for node in nodes.iter().filter(|n| n.visible) {\n                if points.len() >= super::BUDGET { break; }\n                let include = inherited || selected.contains(&node.id);\n                if include && let NodeKind::Text(t) = &node.kind {\n                    let layout = super::layout_text(super::FontDb::global(), t);\n                    if layout.lines.len() == 1 {\n                        let available = super::BUDGET - points.len();\n                        points.extend(layout.glyphs.iter().flat_map(|g| g.outline.segments())\n                            .map(|s| t.xf * s.start()).filter(|p| p.is_finite())\n                            .take(available).map(|p| (p, Kind::Anchor)));\n                    }\n                }\n                if let Some(children) = node.children() {\n                    let shown = children.get(usize::from(node.extras().shaper.is_some())..).unwrap_or_default();\n                    selected_text(shown, selected, include, points);\n                }\n            }\n        }\n        selected_text(&cx.doc.layers, &selected, false, &mut sources.points);\n        for &(p, kind) in &sources.points {\n            sources.xs.push((p.x, p, kind));\n            sources.ys.push((p.y, p, kind));\n        }\n        Self {\n            sources: sources.index().styled(cx),\n            targets: Targets::glyph_move_targets(cx, &cx.selection.objects),\n            lock: Cell::new(None),\n        }\n    }\n\n    fn snap(&self, start: Point, d: Vec2, copy: bool, acquire: f64, release: f64, direction: Option<Vec2>) -> Option<(Vec2, Vec<Overlay>)> {\n        let at = start + d;\n        if !super::within(&self.sources.points, |(p, _)| p.x, start.x, 1e-7).iter()\n            .any(|(p, _)| p.distance(start) <= 1e-7)\n        {\n            return None;\n        }\n        let correction = |p: Point, axis: Option<bool>| match axis {\n            None => p - at,\n            Some(true) => Vec2::new(p.x - at.x, 0.0),\n            Some(false) => Vec2::new(0.0, p.y - at.y),\n        };\n        let amount = |p, axis| correction(p, axis).hypot();\n        let allowed = |p, axis| direction.is_none_or(|dir| on_direction(correction(p, axis), dir));\n        let sets = [Some(&self.targets), copy.then_some(&self.sources)];\n        let exact = sets.into_iter().flatten().flat_map(|t| super::within(&t.points, |(p, _)| p.x, at.x, acquire))\n            .map(|(p, _)| *p)\n            .filter(|p| p.distance(at) <= acquire && allowed(*p, None))\n            .min_by(|a, b| a.distance(at).total_cmp(&b.distance(at)));\n        let held = self.lock.get().filter(|&(p, axis)| amount(p, axis) <= release && allowed(p, axis));\n        let choice = held.filter(|(_, axis)| axis.is_none())\n            .or(exact.map(|p| (p, None))).or(held)\n            .or_else(|| {\n                sets.into_iter().flatten().flat_map(|t| [(&t.xs, at.x, true), (&t.ys, at.y, false)])\n                    .flat_map(|(lines, v, x)| super::lines_near(lines, v, acquire).iter().map(move |&(_, p, _)| (p, Some(x))))\n                    .filter(|&(p, axis)| allowed(p, axis))\n                    .min_by(|&(a, x), &(b, y)| amount(a, x).total_cmp(&amount(b, y)).then_with(|| a.distance(at).total_cmp(&b.distance(at))))\n            });\n        self.lock.set(choice);\n        let (target, axis) = choice?;\n        let next = if axis.is_none() { target - start } else { d + correction(target, axis) };\n        let mut guides = move_hit_guides(&self.targets, target, \"anchor\", ANCHOR_HIT);\n        if axis.is_some() && self.targets.style.lines {\n            guides.push(Overlay::Line { a: start + next, b: target, color: self.targets.style.color, dashed: false });\n        }\n        Some((next, guides))\n    }\n}\n\nfn move_hit_guides(targets: &Targets", 1),
        ("    fn move_snap(bounds: Rect, sources: Vec<Point>, targets: Targets) -> ObjectMoveSnap {", "    #[test]\n    fn leo_object_move_grabs_and_highlights_live_glyph_anchors() {\n        use crate::testutil::{cx, paint};\n        use vectorcraft_doc::{CharStyle, TextObject};\n\n        let mut doc = Document::new(800.0, 600.0);\n        let layer = doc.layers[0].id;\n        let source = doc.alloc_id();\n        let target = doc.alloc_id();\n        let style = CharStyle { size: 60.0, ..Default::default() };\n        let moving = TextObject::point(Point::new(120.0, 250.0), \"H\", style.clone());\n        let stationary = TextObject::point(Point::new(360.0, 160.0), \"H\", style);\n        let expected = Vec2::new(240.0, -90.0);\n        let layout = super::super::layout_text(super::super::FontDb::global(), &moving);\n        let outline = &layout.glyphs.first().expect(\"a visible glyph\").outline;\n        let bbox = outline.bounding_box();\n        let corner = outline.segments().map(|s| s.start())\n            .find(|p| p.x > bbox.x0 + 1.0 && p.x < bbox.x1 - 1.0 && p.y > bbox.y0 + 1.0 && p.y < bbox.y1 - 1.0)\n            .expect(\"a corner inside H\");\n        let grab = moving.xf * corner;\n        let hit = stationary.xf * corner;\n        doc.insert(Some(layer), 0, Node::new(source, NodeKind::Text(Box::new(moving)))).unwrap();\n        doc.insert(Some(layer), 1, Node::new(target, NodeKind::Text(Box::new(stationary)))).unwrap();\n        let mut selection = Selection::default();\n        selection.set([source]);\n        let paint = paint();\n        let cx = ToolContext { leo_snapping: true, smart_guides: true, snap_to_glyph: true, ..cx(&doc, &selection, &paint) };\n        assert_eq!(super::super::grab_glyph_anchor(&cx, source, grab, 2.0), Some(grab));\n        let glyph = GlyphMoveSnap::new(&cx);\n        assert!(glyph.targets.points.iter().all(|(p, _)| *p != grab), \"no self-snap on move\");\n        let (delta, guides) = glyph.snap(grab, expected + Vec2::new(1.0, -1.0), false, 8.0, 12.8, None).unwrap();\n        assert!((delta - expected).hypot() < 1e-8);\n        assert!(guides.iter().any(|g| matches!(g, Overlay::CurvePoint { p, .. } if p.distance(hit) < 1e-8)));\n\n        glyph.lock.set(None);\n        let raw = expected + Vec2::new(-1.0, 160.0);\n        let (aligned, guides) = glyph.snap(grab, raw, false, 8.0, 12.8, Some(Vec2::new(1.0, 0.0))).unwrap();\n        assert_eq!(aligned.y, raw.y);\n        assert!(guides.iter().any(|g| matches!(g, Overlay::Line { a, b, .. } if a.x == b.x)));\n        assert!(glyph.snap(grab, Vec2::ZERO, true, 8.0, 12.8, None).is_some());\n        assert!(matches!(doc.node(source).map(|n| &n.kind), Some(NodeKind::Text(_))));\n        let disabled = ToolContext { snap_to_glyph: false, ..cx };\n        assert!(ObjectMoveSnap::new(&disabled, None).glyph.is_none());\n    }\n\n    fn move_snap(bounds: Rect, sources: Vec<Point>, targets: Targets) -> ObjectMoveSnap {", 1),
    ],
}
for relative, replacements in edits.items():
    path = root / relative
    source = path.read_text(encoding="utf-8")
    for old, new, count in replacements:
        if source.count(old) != count:
            raise SystemExit(f"Unexpected {relative} source: {old[:80]}")
        source = source.replace(old, new)
    path.write_text(source, encoding="utf-8", newline="\n")
